-- 065: 32 стиля, продающие названия и библиотека стилей.
-- В основном сценарии показываем 10 featured; остальные доступны в /styles.
-- Существующие ключи modern/boho/country переиспользуем, чтобы не упасть на UNIQUE(name).

ALTER TABLE styles ADD COLUMN IF NOT EXISTS display_name TEXT;
ALTER TABLE styles ADD COLUMN IF NOT EXISTS family TEXT;
ALTER TABLE styles ADD COLUMN IF NOT EXISTS era TEXT;
ALTER TABLE styles ADD COLUMN IF NOT EXISTS is_featured BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE styles ADD COLUMN IF NOT EXISTS seo_name TEXT;

-- Переиспользуем строки, которые уже есть с теми же именами.
UPDATE styles SET key = 'modern' WHERE name = 'Современный' AND key <> 'modern';
UPDATE styles SET key = 'boho' WHERE name = 'Бохо' AND key <> 'boho';
UPDATE styles SET key = 'country' WHERE name = 'Кантри' AND key <> 'country';

INSERT INTO styles (key, name, display_name, family, era, is_featured, accent, prompt_description, description, swatches, active, sort) VALUES
  ('modern', 'Современный', 'Миланская нежность', 'Современные', '2020s', true, 'graphite', 'A contemporary interior of the 2020s: clean architectural lines, walls in warm limewash plaster #F4F2EE (soft cream), one deep petrol accent wall #2F5D62, walnut veneer cabinetry, brushed metal and glass details, a few sculptural objects styled on shelves. Integrated warm 3000K lighting washes the plaster, soft daylight from tall windows fills the room with even illumination. Eye-level 35mm lens, straight verticals, editorial architectural photography, medium-format look.', 'Плотный городской минимализм: тёплый грейдж, ореховый шпон и один глубокий акцент.', '[{"hex":"#F4F2EE","name":"основной"},{"hex":"#CBC6BD","name":"поддерживающий"},{"hex":"#33322F","name":"тёмный"},{"hex":"#2F5D62","name":"акцент"}]', true, 10),
  ('loft', 'Лофт', 'Бруклинский ритм', 'Современные', 'industrial', true, 'graphite', 'An industrial loft living room: exposed brick wall #A8563A (rusty red), raw concrete ceiling, black steel window frames, worn leather sofa in warm brown, reclaimed wood coffee table, open pipes and ducts left visible. Hard directional daylight from tall factory windows casts long dramatic shadows across the brick. Eye-level 28mm wide lens, slight perspective depth, editorial urban photography, gritty but warm.', 'Кирпич, бетон и чёрный металл: индустриальность с тёплым жилым характером.', '[{"hex":"#B0A89A","name":"основной"},{"hex":"#6E6A63","name":"поддерживающий"},{"hex":"#4A4640","name":"тёмный"},{"hex":"#A8563A","name":"акцент"}]', true, 20),
  ('scandinavian', 'Скандинавский', 'Копенгагенский свет', 'Современные', 'nordic', true, 'dust', 'A bright Scandinavian living room: white walls #FAF8F4 (warm white), light oak floor and furniture, natural linen curtains diffusing soft overcast daylight from the window, wool throw in sage #8A9A8B, ceramic vases and one terracotta accent cushion #C26D5A. Soft even northern light, gentle shadows, calm and airy. Eye-level 35mm lens, editorial interior photography, warm minimal styling, medium-format grain.', 'Светлый дуб, лён и много мягкого дневного света — северный уют без тяжести.', '[{"hex":"#FAF8F4","name":"основной"},{"hex":"#D8CFC2","name":"поддерживающий"},{"hex":"#8A9A8B","name":"тёмный"},{"hex":"#C26D5A","name":"акцент"}]', true, 30),
  ('provence', 'Прованс', 'Лавандовое поле', 'Тёплые / природные', 'french-country', true, 'dust', 'A french provence kitchen: cream walls #F6F1E7, aged wood table and cabinets, natural linen curtains, ceramic pitchers, wrought iron details, lavender in a jug #9B7FA6, sage green shutters #7E8B72. Bright soft daylight from a window over the sink, gentle romantic country mood, pastel palette. Eye-level 35mm lens, sunlit editorial farmhouse photography.', 'Французский юг: пастель, состаренное дерево, лён и лаванда.', '[{"hex":"#F6F1E7","name":"основной"},{"hex":"#D9CBB4","name":"поддерживающий"},{"hex":"#7E8B72","name":"тёмный"},{"hex":"#9B7FA6","name":"акцент"}]', true, 40),
  ('minimalism', 'Современный минимализм', 'Токийская лёгкость', 'Современные', 'modern', true, 'sand', 'A quiet minimalist interior: matte microcement floor, off-white walls #F5F3EF, one low MDF sideboard in greige #C9C4BB, a single sculptural ceramic object, nothing else on surfaces. Soft diffuse daylight from a hidden window, even illumination, deep negative space, straight verticals. Eye-level 35mm lens, calm editorial minimalism, generous empty floor area, matte finishes only.', 'Воздух, тишина и минимум предметов: пространство важнее вещей.', '[{"hex":"#F5F3EF","name":"основной"},{"hex":"#C9C4BB","name":"поддерживающий"},{"hex":"#2E2E2C","name":"тёмный"},{"hex":"#B7A99A","name":"акцент"}]', true, 50),
  ('neoclassic', 'Неоклассика', 'Парижская классика', 'Классика', 'neoclassical', true, 'sand', 'A neoclassical living room: herringbone parquet floor, wall moldings and a quiet cornice, walls in warm ivory #F2EDE4, one deep navy accent armchair #1F3A5F, brass sconces glowing at 2700K on both sides of a mirror, light velvet sofa. Symmetrical balanced lighting, soft daylight through linen curtains, timeless proportions. Eye-level 35mm lens, elegant editorial classicism, medium-format look.', 'Светлая классика без тяжести: паркет ёлочкой, лепнина, латунь и бархат.', '[{"hex":"#F2EDE4","name":"основной"},{"hex":"#D6CCBA","name":"поддерживающий"},{"hex":"#9A8F7D","name":"тёмный"},{"hex":"#1F3A5F","name":"акцент"}]', true, 60),
  ('boho', 'Бохо', 'Марракеш-текстиль', 'Тёплые / природные', 'bohemian', true, 'terra', 'A bohemian living room: layered textiles in warm earth tones #EFE3D2, rattan chairs and hanging macrame, wool kilim rug in terracotta #B4553F, leather pouf, many living plants at three heights, collected ceramics and woven baskets. Dappled soft light through sheer curtains, relaxed layered mood, tactile surfaces everywhere. Eye-level 35mm lens, free-spirited editorial interior photography.', 'Слои ткани, макраме, растения и собранная годами свобода.', '[{"hex":"#EFE3D2","name":"основной"},{"hex":"#C9A77C","name":"поддерживающий"},{"hex":"#5B4636","name":"тёмный"},{"hex":"#B4553F","name":"акцент"}]', true, 70),
  ('baroque', 'Современное барокко', 'Версальское очарование', 'Классика', 'baroque', true, 'terra', 'A modern baroque interior: restrained curved furniture in deep burgundy velvet #7C1F2E, marble surfaces, gilded moldings #C9A961 on a warm cream wall #F3EAD9, crystal chandelier, silk curtains. Dramatic layered lighting with strong chiaroscuro, jewel tones, contemporary furniture silhouettes keep it modern rather than a palace. Eye-level 35mm lens, glamorous editorial interior photography.', 'Бархат, золото и драма, но в современных силуэтах — без дворцового китча.', '[{"hex":"#F3EAD9","name":"основной"},{"hex":"#C9A961","name":"поддерживающий"},{"hex":"#3B2233","name":"тёмный"},{"hex":"#7C1F2E","name":"акцент"}]', true, 80),
  ('japandi', 'Джапанди', 'Киотская тишина', 'Современные', 'japandi', true, 'forest', 'A calm japandi bedroom: low oak platform bed with linen bedding, walls in warm rice-paper tone #EDE8DF, one dark walnut low cabinet #4A4A45, paper lantern pendant glowing warm at 2700K, sheer linen curtains filtering soft daylight, one dried branch in a lumpy ceramic vase. Quiet soft light with gentle shadows, tactile plaster and wood, generous negative space. Eye-level 35mm lens, wabi-sabi stillness, editorial interior photography.', 'Тёплый минимализм, дуб и орех, рисовая бумага и лён — тишина и гармония.', '[{"hex":"#EDE8DF","name":"основной"},{"hex":"#B9B0A2","name":"поддерживающий"},{"hex":"#4A4A45","name":"тёмный"},{"hex":"#7A8377","name":"акцент"}]', true, 90),
  ('classic', 'Классический', 'Лондонская библиотека', 'Классика', 'classic', true, 'sand', 'A traditional classic living room: dark walnut paneling and parquet #4A2E22, brocade armchairs in burgundy #6E1F2A, bronze chandelier glowing warm, Persian rug with deep red pattern, wall moldings, one antique cabinet with curved legs. Formal symmetrical composition, soft warm light, collected antiques, a room with history. Eye-level 35mm lens, timeless editorial interior photography.', 'Тёмное дерево, антиквариат, персидский ковёр и парадная симметрия.', '[{"hex":"#EDE4D3","name":"основной"},{"hex":"#B79B6E","name":"поддерживающий"},{"hex":"#4A2E22","name":"тёмный"},{"hex":"#6E1F2A","name":"акцент"}]', true, 100),
  ('country', 'Кантри', 'Тосканская усадьба', 'Тёплые / природные', 'rustic', false, 'forest', 'A rustic country kitchen: painted wood cabinets #EFE7D8, exposed brick wall #A0432F, cast iron cookware, enamel pitchers, checked linen tablecloth, large wooden farmhouse table, copper pots hanging. Bright honest daylight, warm practical farm mood, sturdy materials. Eye-level 35mm lens, rustic editorial photography, warm earthy palette.', 'Кирпич, чугун, эмаль и большой деревянный стол — честная ферма.', '[{"hex":"#EFE7D8","name":"основной"},{"hex":"#B98A5E","name":"поддерживающий"},{"hex":"#5A4632","name":"тёмный"},{"hex":"#A0432F","name":"акцент"}]', true, 110),
  ('art_nouveau', 'Модерн (ар-нуво)', 'Брюссельская грация', 'Акцентные', '1900s', false, 'forest', 'An art nouveau interior of the 1900s: flowing organic lines in curved wood furniture, stained glass window with botanical pattern in mauve #8A5A83 and sage #B5C0A5, wrought iron details, silk cushions, brass lamp with a whiplash stem. Soft warm daylight through the stained glass, decorative elegance built on flowing curved lines throughout. Eye-level 35mm lens, romantic editorial interior photography.', 'Текучие растительные линии, витраж и гнутое дерево 1900-х.', '[{"hex":"#EFE9DA","name":"основной"},{"hex":"#B5C0A5","name":"поддерживающий"},{"hex":"#4A3B2A","name":"тёмный"},{"hex":"#8A5A83","name":"акцент"}]', true, 120),
  ('english', 'Английский', 'Честерфилд-уют', 'Классика', 'english', false, 'forest', 'An english club interior: deep green walls #2F3B33, leather chesterfield sofa in chestnut brown, built-in bookcases filled with old books, brass reading lamps glowing warm, tartan wool blanket in burgundy #6B2B2B, fireplace with a carved mantel. Moody low light with warm pools around the lamps, layered club comfort. Eye-level 35mm lens, cozy traditional editorial photography.', 'Кожаный Честерфилд, книги, камин и клетка — английский клуб.', '[{"hex":"#E6DCC8","name":"основной"},{"hex":"#8E6B4A","name":"поддерживающий"},{"hex":"#2F3B33","name":"тёмный"},{"hex":"#6B2B2B","name":"акцент"}]', true, 130),
  ('eclectic', 'Эклектика', 'Парижский блошиный рынок', 'Акцентные', 'eclectic', false, 'graphite', 'An eclectic interior: curated mix of two or three eras, a vintage armchair next to a contemporary sofa, gallery wall with mismatched frames, one teal accent wall #2E6B6B, layered textiles in one coherent palette #F0EAE0, collected objects on every surface but composed, not cluttered. Soft even daylight, intentional curation. Eye-level 35mm lens, editorial interior photography.', 'Смешение 2–3 эпох в одной палитре: винтаж, галерея и слои текстиля.', '[{"hex":"#F0EAE0","name":"основной"},{"hex":"#C2B49C","name":"поддерживающий"},{"hex":"#3A3A38","name":"тёмный"},{"hex":"#2E6B6B","name":"акцент"}]', true, 140),
  ('mediterranean', 'Средиземноморский', 'Амальфи-берег', 'Тёплые / природные', 'mediterranean', false, 'terra', 'A mediterranean interior: whitewashed walls #F7F3EA, terracotta floor tiles, aged wood beams, wrought iron details, olive green shutters #A8B5A0, dusty blue accents #3F6E8E, lemons in a ceramic bowl on a stone table. Warm sunlight streaming through open shutters, sun-bleached surfaces, coastal air. Eye-level 35mm lens, bright editorial mediterranean photography.', 'Побелка, терракота, оливковая тень и солнечный юг.', '[{"hex":"#F7F3EA","name":"основной"},{"hex":"#E3D5B8","name":"поддерживающий"},{"hex":"#A8B5A0","name":"тёмный"},{"hex":"#3F6E8E","name":"акцент"}]', true, 150),
  ('eco', 'Эко / органический модерн', 'Балийское тепло', 'Тёплые / природные', 'organic', false, 'forest', 'An organic modern living room: warm limewash walls #EAE4D8, rattan armchairs with linen cushions, natural stone coffee table, large monstera and ficus plants near the window, wool rug in earthy beige. Dappled daylight through sheer linen curtains creates soft moving light patches, olive green #7C8A6E accents, warm terracotta pottery #A4713E. Eye-level 35mm lens, wellness mood, tactile natural materials, editorial interior photography.', 'Лён, ратанг, камень и живая зелень — wellness и природное тепло.', '[{"hex":"#EAE4D8","name":"основной"},{"hex":"#C8B89A","name":"поддерживающий"},{"hex":"#7C8A6E","name":"тёмный"},{"hex":"#A4713E","name":"акцент"}]', true, 160),
  ('art_deco', 'Ар-деко', 'Гэтсби-шик', 'Классика', '1920s', false, 'terra', 'An art deco interior: geometric inlay panels in dark navy #1E2A38 and gold #C9A961, velvet armchair in oxblood #6E3B3B, marble floor with fan pattern, polished brass details, symmetrical composition with a sunburst mirror as focal point. Glamorous warm lighting with sparkle on metal and glass, rich jewel tones. Eye-level 35mm lens, 1920s jazz-age elegance, editorial photography.', 'Джаз, геометрия и золото: роскошь 1920-х в строгих линиях.', '[{"hex":"#EFE8DB","name":"основной"},{"hex":"#C9A961","name":"поддерживающий"},{"hex":"#1E2A38","name":"тёмный"},{"hex":"#6E3B3B","name":"акцент"}]', true, 170),
  ('dark_contemporary', 'Тёмный контемпорари', 'Миланский графит', 'Современные', '2020s', false, 'graphite', 'A dark contemporary interior: smoked oak veneer panels #232323 (graphite), dark stone surfaces, brushed brass details #C9A227, low warm accent lighting grazing the wood grain, deep shadows in corners, one sculptural lamp as the single bright point. Moody layered 2700K light from hidden sources, dramatic chiaroscuro, calm and precise. Eye-level 35mm lens, editorial dark minimalism, matte finishes with one metal highlight.', 'Дымчатый дуб, графит и латунь: тёмный, но не мрачный.', '[{"hex":"#232323","name":"основной"},{"hex":"#3A3A38","name":"поддерживающий"},{"hex":"#1A1A19","name":"тёмный"},{"hex":"#C9A227","name":"акцент"}]', true, 180),
  ('memphis_accent', 'Мемфис-акцент', 'Миланские 80-е', 'Акцентные', '1980s', false, 'terra', 'A memphis accent interior: neutral shell in warm white #F4F1EC, one bold coral-red sculptural object #E4583E, glossy laminate sideboard with playful geometry, chrome details, graphic black lines #2E2E2C on one wall, arc lamp. Even bright lighting, crisp 1980s postmodern energy, restrained so the accent object stays the hero. Eye-level 35mm lens, graphic editorial photography.', 'Геометрия, глянец и один смелый акцент — постмодерн 80-х.', '[{"hex":"#F4F1EC","name":"основной"},{"hex":"#DAD4C8","name":"поддерживающий"},{"hex":"#2E2E2C","name":"тёмный"},{"hex":"#E4583E","name":"акцент"}]', true, 190),
  ('mid_century', 'Мид-сенчури', 'Палм-Спрингс 50-х', 'Современные', '1950s', false, 'terra', 'A mid-century modern living room: low walnut credenza on tapered legs, cream bouclé sofa #EFE6D8, brass floor lamp with a sputnik head, geometric wool rug in olive and burnt orange #C26D3A, floor-to-ceiling windows with soft afternoon light, one monstera plant. Warm directional sunlight from the right casts short shadows, brass and teak reflections. Eye-level 35mm lens, 1950s Palm Springs mood, editorial retro photography.', 'Тик, латунь, органические формы и торшеры-«солнышки» — Америка 50-х.', '[{"hex":"#EFE6D8","name":"основной"},{"hex":"#C8B49A","name":"поддерживающий"},{"hex":"#6B4E3A","name":"тёмный"},{"hex":"#C26D3A","name":"акцент"}]', true, 200),
  ('soviet_modern', 'Советский модернизм', 'Брежневская романтика', 'Современные', '1970s', false, 'sand', 'A soviet modernist living room of the 1970s: veneered wall unit in warm oak, parquet floor, geometric wool rug in ochre and green, fabric-shaded table lamp glowing warm, a framed soviet-era poster on the wall #B5A47C, two low armchairs with wooden armrests. Soft even ceiling light, modest comfort, functional layout. Eye-level 35mm lens, nostalgic documentary photography, warm ochre and sage palette.', 'Шпон, паркет и советский плакат: узнаваемая романтика 1970-х.', '[{"hex":"#E8DFC8","name":"основной"},{"hex":"#B5A47C","name":"поддерживающий"},{"hex":"#5A4E3A","name":"тёмный"},{"hex":"#8A6B3F","name":"акцент"}]', true, 210),
  ('bauhaus', 'Баухаус', 'Дессау-геометрия', 'Современные', '1920s', false, 'graphite', 'A bauhaus interior: tubular steel armchairs with black leather, glass coffee table, white walls #F2F0EA, one red accent panel #C23A2E and one blue cushion #2A5A8A, wooden cabinet with clean geometric fronts. Even functional lighting, crisp geometry, form follows function with clean unornamented surfaces. Eye-level 35mm lens, straight verticals, graphic composition, editorial architecture photography.', 'Сталь, стекло и первичные цвета: форма следует функции.', '[{"hex":"#F2F0EA","name":"основной"},{"hex":"#C9C4B8","name":"поддерживающий"},{"hex":"#2E2E2C","name":"тёмный"},{"hex":"#C23A2E","name":"акцент"}]', true, 220),
  ('dark_academia', 'Тёмная академия', 'Оксфордская романтика', 'Классика', 'academia', false, 'forest', 'A dark academia study: deep green walls #2A2E26, floor-to-ceiling wooden bookshelves packed with old books, leather armchair, brass desk lamp casting a warm cone of light, candles on the desk, Persian rug in faded tones, dried flowers in a vase. Moody low-key lighting with deep soft shadows, scholarly quiet atmosphere. Eye-level 35mm lens, cinematic editorial photography, film grain.', 'Книги, кожа, свечи и глубокий зелёный — университетская романтика.', '[{"hex":"#2A2E26","name":"основной"},{"hex":"#4A4638","name":"поддерживающий"},{"hex":"#1A1C18","name":"тёмный"},{"hex":"#8A6B3F","name":"акцент"}]', true, 230),
  ('modern_farmhouse', 'Современная ферма', 'Норманская усадьба', 'Тёплые / природные', 'farmhouse', false, 'forest', 'A modern farmhouse kitchen: white shiplap walls #F6F3EA, black steel window frames, reclaimed wood dining table, vintage metal pendant lights glowing warm, checked linen towels, ceramic pitchers on open shelves, exposed wooden beams. Bright soft daylight from large windows, clean and cozy. Eye-level 35mm lens, warm honest country mood, editorial farmhouse photography.', 'Белые стены, чёрные рамы и шипшина — светлая современная ферма.', '[{"hex":"#F6F3EA","name":"основной"},{"hex":"#D8CBB8","name":"поддерживающий"},{"hex":"#4A4438","name":"тёмный"},{"hex":"#2F3B33","name":"акцент"}]', true, 240),
  ('coastal', 'Прибрежный / Хэмптонс', 'Хэмптонс-лёгкость', 'Тёплые / природные', 'coastal', false, 'dust', 'A hamptons coastal living room: white walls #F5F2EA, linen sofas, rattan chairs, driftwood coffee table, soft blue cushions #A8C4D4 and sea-glass accents #5A7A8A, sheer white curtains moving in the breeze. Airy bright daylight from large windows facing the ocean, light and breezy atmosphere. Eye-level 35mm lens, bright coastal editorial photography.', 'Белый, голубой, лён и ратанг — морская лёгкость Хэмптонса.', '[{"hex":"#F5F2EA","name":"основной"},{"hex":"#C9D4D8","name":"поддерживающий"},{"hex":"#5A7A8A","name":"тёмный"},{"hex":"#A8C4D4","name":"акцент"}]', true, 250),
  ('space_age', 'Космическая эра (1960s)', 'Кубрик-2001', 'Акцентные', '1960s', false, 'terra', 'A space age interior of the 1960s: rounded plastic chairs in mustard #E4A83A and cream #F0E8E0, chrome details, bubble pendant lamp, vinyl bench with soft curves, glossy surfaces, futuristic optimism, clean circular shapes. Even bright lighting with soft reflections, atomic age mood. Eye-level 35mm lens, retro-futuristic editorial photography.', 'Пластик, хром и скруглённые формы — космический оптимизм 1960-х.', '[{"hex":"#F0E8E0","name":"основной"},{"hex":"#C8B8A8","name":"поддерживающий"},{"hex":"#4A4438","name":"тёмный"},{"hex":"#E4A83A","name":"акцент"}]', true, 260),
  ('grandmillennial', '«Бабушкин шик»', 'Английская роза', 'Классика', 'grandmillennial', false, 'dust', 'A grandmillennial living room: floral wallpaper in dusty rose #C28A8A on cream #F2EAE0, vintage wooden furniture with curved legs, pleated lampshades glowing warm, ceramic vases with fresh flowers, layered textiles with fringe and embroidery, framed botanical prints on the walls. Soft daylight through lace curtains, cozy layered traditional mood. Eye-level 35mm lens, romantic editorial interior photography.', 'Обои в цветочек, плиссированные абажуры и винтаж — цветочный уют.', '[{"hex":"#F2EAE0","name":"основной"},{"hex":"#D8C4B0","name":"поддерживающий"},{"hex":"#7A6A5A","name":"тёмный"},{"hex":"#C28A8A","name":"акцент"}]', true, 270),
  ('desert_modern', 'Пустынный модерн', 'Санта-Фе теплота', 'Тёплые / природные', 'desert', false, 'terra', 'A desert modern interior: terracotta plaster walls #E8D4C0, natural stone floor, one large cactus in a clay pot, low wooden bench with woven textile, large windows framing dry landscape, hand-thrown ceramics on a stone ledge. Warm dry sunlight raking across the plaster, long soft shadows, sparse calm composition. Eye-level 35mm lens, warm minimal editorial photography.', 'Терракота, кактусы и камень — сухой тёплый минимализм.', '[{"hex":"#E8D4C0","name":"основной"},{"hex":"#C4A48C","name":"поддерживающий"},{"hex":"#8A6A52","name":"тёмный"},{"hex":"#C47A4A","name":"акцент"}]', true, 280),
  ('tropical_modern', 'Тропический модерн', 'Тулум-нега', 'Тёплые / природные', 'tropical', false, 'forest', 'A tropical modern interior: bamboo and rattan furniture, white walls #F0E8D8, dark wood beams, lush palm and fern plants near open doors, linen cushions in moss green #2E6B4A, woven pendant lamps glowing warm. Dappled daylight through palm leaves, humid open-air atmosphere, layered greenery. Eye-level 35mm lens, tropical editorial interior photography.', 'Бамбук, зелень и открытые пространства — влажная тропическая нега.', '[{"hex":"#F0E8D8","name":"основной"},{"hex":"#B8C8A0","name":"поддерживающий"},{"hex":"#4A5A3A","name":"тёмный"},{"hex":"#2E6B4A","name":"акцент"}]', true, 290),
  ('neo_deco', 'Нео-деко', 'Новый Гэтсби', 'Акцентные', '2020s', false, 'terra', 'A neo deco interior: red marble surfaces #A83A3A, brushed brass details, velvet sofa in warm brown, geometric textile patterns, color-drenched deep wall #2E1E24, soft geometric forms instead of strict 1920s lines, modern art deco revival. Glamorous warm lighting with sparkle, rich layered materials. Eye-level 35mm lens, contemporary editorial photography.', 'Ар-деко 2026: красный мрамор, латунь, colour drenching.', '[{"hex":"#F0E4D8","name":"основной"},{"hex":"#C4A88A","name":"поддерживающий"},{"hex":"#2E1E24","name":"тёмный"},{"hex":"#A83A3A","name":"акцент"}]', true, 300),
  ('high_tech', 'Хай-тек', 'Токио-глянец', 'Современные', 'futuristic', false, 'graphite', 'A high-tech interior: chrome and glass surfaces, glossy white laminate #F0F2F4, brushed steel details, integrated cool LED lines #4A90A8 under cabinets and along the ceiling, glass partition wall. Even clinical illumination with precise reflections, crisp geometry with cables fully concealed. Eye-level 35mm lens, technological minimalism, futuristic clean aesthetic, editorial photography.', 'Хром, стекло и LED-линии — технологичный глянцевый минимализм.', '[{"hex":"#F0F2F4","name":"основной"},{"hex":"#B8BEC4","name":"поддерживающий"},{"hex":"#2E3438","name":"тёмный"},{"hex":"#4A90A8","name":"акцент"}]', true, 310),
  ('chalet', 'Шале', 'Шамони-тепло', 'Тёплые / природные', 'alpine', false, 'forest', 'An alpine chalet interior: solid wood walls and beams in warm honey tones #E8DFD0, stone fireplace with a crackling fire, sheepskin throws and wool blankets in rust #7A4A3A, wrought iron candle holders, carved wooden furniture, mountain view through a small window. Warm soft firelight from the hearth, gentle shadows, cozy layered mountain atmosphere. Eye-level 35mm lens, alpine editorial interior photography.', 'Дерево, камень и камин — альпийский уют Шамони.', '[{"hex":"#E8DFD0","name":"основной"},{"hex":"#B89A72","name":"поддерживающий"},{"hex":"#5A4632","name":"тёмный"},{"hex":"#7A4A3A","name":"акцент"}]', true, 320)
ON CONFLICT (key) DO UPDATE SET
  name = EXCLUDED.name,
  display_name = EXCLUDED.display_name,
  family = EXCLUDED.family,
  era = EXCLUDED.era,
  is_featured = EXCLUDED.is_featured,
  accent = EXCLUDED.accent,
  prompt_description = EXCLUDED.prompt_description,
  description = EXCLUDED.description,
  swatches = EXCLUDED.swatches,
  active = true,
  sort = EXCLUDED.sort,
  updated_at = now();

-- SEO-имя совпадает с академическим названием.
UPDATE styles SET seo_name = name
WHERE key IN (
  'modern', 'loft', 'scandinavian', 'provence', 'minimalism', 'neoclassic',
  'boho', 'baroque', 'japandi', 'classic', 'country', 'art_nouveau',
  'english', 'eclectic', 'mediterranean', 'eco', 'art_deco',
  'dark_contemporary', 'memphis_accent', 'mid_century', 'soviet_modern',
  'bauhaus', 'dark_academia', 'modern_farmhouse', 'coastal', 'space_age',
  'grandmillennial', 'desert_modern', 'tropical_modern', 'neo_deco',
  'high_tech', 'chalet'
);
